#include <bits/stdc++.h>
using namespace std;

int f(int x, int l, int r) {
    return (x % (l + r)) / l;
}

bool solve(vector<int>& v, int l, int r) {
    int fold = 0;
    for(const auto u : v) fold ^= f(u, l, r);
    return fold != 0;
}

int main() {
    int n, l, r;
    cin >> n >> l >> r;
    vector<int> a(n);
    for(auto& v : a) cin >> v;
    cout << (solve(a, l, r) ? "First\n" : "Second\n");
}
